using namespace std;

vector<int> solution(vector<int> &input)
{
    sort(input.begin(), input.end());

    vector<int> res; 
    for (int i = 2; i*i <= input[0]; ++i)
    {
        if (input[0] % i == 0)
        {
            vector<int> temp;
            while (input[0] % i == 0)
                input[0] /= i;

            temp.push_back(i);
            if (i!= input[0])
            {
                temp.push_back(input[0]);
                input[0] = 1;
            }
            if (i!= 2)
                swap(temp[0], temp[1]); 

            res.insert(res.end(), temp.begin(), temp.end());
        }
    }

    return res;
} 

